   @Override
   public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
       // Only process if the root element is network-security-config
       Element root = element.getOwnerDocument().getDocumentElement();
       if (root == null || !root.getTagName().equals("network-security-config")) {
           return;
       }

       if (element.getTagName().equals("pin-set")) {
           int pinCount = 0;
           NodeList children = element.getChildNodes();
           for (int i = 0; i < children.getLength(); i++) {
               Node child = children.item(i);
               if (child.getNodeType() == Node.ELEMENT_NODE && child.getNodeName().equals("pin")) {
                   pinCount++;
               }
           }
           if (pinCount == 1) {
               context.report(ISSUE, element, context.getLocation(element),
                   "Missing backup pin. It is highly recommended to declare a backup `<pin>` element.");
           }
       }
   }
   ```

